```cpp
#include <iostream>
#include <fstream>
#include <filesystem>
#include <vector>
#include <string>
#include <algorithm> // Necessário para std::find
#include <cryptopp/keccak.h>
#include <cryptopp/hex.h>
#include <cryptopp/files.h>

namespace fs = std::filesystem;

// Estrutura para armazenar o caminho do arquivo e seu hash
struct FileHashEntry {
    std::string filename;
    std::string fullPath;
    std::string hash;
};

// Função para calcular o hash Keccak-512 de um arquivo
std::string calculateKeccak512(const std::string& filePath) {
    CryptoPP::Keccak_512 hash;
    std::string digest;

    try {
        CryptoPP::FileSource(filePath.c_str(), true,
            new CryptoPP::HashFilter(hash,
                new CryptoPP::HexEncoder(
                    new CryptoPP::StringSink(digest), true)));
    } catch (const CryptoPP::Exception& e) {
        std::cerr << "Erro ao calcular hash para " << filePath << ": " << e.what() << std::endl;
        return ""; // Retorna vazio em caso de erro
    }
    return digest;
}

// Função principal
int main() {
    std::vector<FileHashEntry> foundFiles;
    std::vector<std::string> extensions = { ".exe", ".dll", ".asi" };

    std::cout << "Iniciando a varredura de arquivos no diretório atual..." << std::endl;

    // 1. Varredura e Cálculo de Hashes
    for (const auto& entry : fs::directory_iterator(fs::current_path())) {
        if (entry.is_regular_file()) {
            std::string extension = entry.path().extension().string();
            if (std::find(extensions.begin(), extensions.end(), extension) != extensions.end()) {
                std::string filePath = entry.path().string();
                std::string hash = calculateKeccak512(filePath);

                if (!hash.empty()) {
                    foundFiles.push_back({
                        entry.path().filename().string(),
                        filePath,
                        hash
                    });
                }
            }
        }
    }

    // 2. Geração do arquivo rTalesHash.txt (com todos os hashes)
    std::ofstream hashOutputFile("rTalesHash.txt");
    if (!hashOutputFile.is_open()) {
        std::cerr << "Erro ao abrir o arquivo de hash de saída (rTalesHash.txt)!" << std::endl;
        return 1;
    }

    for (const auto& fileEntry : foundFiles) {
        // Formato: "nome_arquivo" : hash
        hashOutputFile << "\"" << fileEntry.filename << "\" : " << fileEntry.hash << std::endl;
    }
    hashOutputFile.close();
    std::cout << "\n✅ Todos os hashes foram calculados e salvos em 'rTalesHash.txt'." << std::endl;

    // 3. Interatividade no Console (Seleção para rTales.ini)
    if (foundFiles.empty()) {
        std::cout << "Nenhum arquivo correspondente aos filtros foi encontrado." << std::endl;
        return 0;
    }

    std::cout << "\n==================================================" << std::endl;
    std::cout << "📚 Lista de Arquivos Encontrados (Selecione para 'rTales.ini'):" << std::endl;
    for (size_t i = 0; i < foundFiles.size(); ++i) {
        std::cout << "[" << i + 1 << "] " << foundFiles[i].filename << std::endl;
    }
    std::cout << "==================================================" << std::endl;

    std::cout << "Digite os números dos arquivos que deseja incluir em 'rTales.ini', separados por vírgula (ex: 1,3,4): ";
    std::string input;
    std::getline(std::cin, input);

    // Processamento da entrada do usuário
    std::vector<int> selectedIndices;
    std::string token;
    std::stringstream ss(input);
    while (std::getline(ss, token, ',')) {
        try {
            // Remove espaços em branco e converte para inteiro
            int index = std::stoi(token);
            if (index > 0 && index <= foundFiles.size()) {
                selectedIndices.push_back(index - 1); // Converte para índice 0-based
            } else {
                std::cerr << "Aviso: Índice " << index << " inválido. Ignorando." << std::endl;
            }
        } catch (const std::invalid_argument& e) {
            std::cerr << "Erro: Entrada inválida. Por favor, use apenas números separados por vírgula." << std::endl;
        }
    }

    // 4. Geração do arquivo rTales.ini (somente os selecionados)
    if (!selectedIndices.empty()) {
        std::ofstream iniOutputFile("rTales.ini");
        if (!iniOutputFile.is_open()) {
            std::cerr << "Erro ao abrir o arquivo de seleção (rTales.ini)!" << std::endl;
            return 1;
        }

        for (int index : selectedIndices) {
            const auto& fileEntry = foundFiles[index];
            // Mantém o formato original para o rTales.ini
            iniOutputFile << "\"" << fileEntry.filename << "\" : " << fileEntry.hash << std::endl;
        }
        iniOutputFile.close();
        std::cout << "\n✅ Sucesso! Os hashes selecionados foram salvos em 'rTales.ini'." << std::endl;
    } else {
        std::cout << "\n⚠️ Nenhuma seleção válida foi feita. Nenhum arquivo 'rTales.ini' foi criado." << std::endl;
    }

    return 0;
}
```

