4. **Lógica principal:** Estruturar a lógica de leitura de arquivos e a função de exibição/cálculo de estatísticas.
5. **Fluxo de execução:** Colocar a lógica que é executada "ao iniciar" (leitura de `relacionamentos.json` e `aki.json`) no final.

### Código Organizado (Sugestão)

Assumindo que você está usando Node.js (pelo uso de `fs`), aqui está uma versão mais estruturada:

```javascript
const fs = require('fs');
// const path = require('path'); // Útil para caminhos

// --- 1. CONSTANTES E DADOS INICIAIS ---
const CASAMENTO_JSON_PATH = './relacionamentos.json';
const AKI_JSON_PATH = './aki.json';

// Estrutura de dados dos jogos (Exemplo)
const jogosAkinator = {
    "LEPRECHAUN RICHES": { min: 0.93, media: 3.59, max: 7.91, chance: 38 }
    // ... outros jogos
};

// --- 2. FUNÇÕES AUXILIARES ---

/**
 * Atualiza os valores estatísticos aplicando uma variação aleatória.
 * @param {object} data - Objeto com min, media, max, chance.
 * @returns {object} Valores ajustados aleatoriamente.
 */
function atualizarValores({ min, media, max, chance }) {
    const variationFactor = (1 + Math.random() * 0.2 - 0.1); // Variação entre 0.9 e 1.1
    return {
        min: min * variationFactor,
        media: media * variationFactor,
        max: max * variationFactor,
        // Chance varia entre chance-5 e chance+4 (mínimo 1, máximo 100)
        chance: Math.max(1, Math.min(100, chance + Math.floor(Math.random() * 10 - 5)))
    };
}

/**
 * Gera a string formatada das estatísticas para um único jogo.
 * @param {string} nome - Nome do jogo.
 * @param {object} valores - Valores calculados (min, media, max, chance).
 * @returns {string} String formatada.
 */
function formatarEstatistica(nome, valores) {
    return `*❲${nome}❳*\n• *Mínimo:* R$ ${valores.min.toFixed(2)}\n• *Média:* R$ ${valores.media.toFixed(2)}\n• *Máximo:* R$ ${valores.max.toFixed(2)}\n• *Chance:* ${valores.chance}%\n\n`;
}

/**
 * Processa e retorna as estatísticas para um jogo específico ou todos.
 * @param {string} jogo - Nome do jogo (ou 'all').
 * @param {object} jogos - Objeto contendo todos os dados dos jogos.
 * @returns {string} A resposta formatada.
 */
function getEstatisticas(jogo, jogos) {
    const header = "🍀 *PORCENTAGENS E ESTATÍSTICAS* 💰\n\n";

    if (jogo === 'all') {
        let resposta = header;
        Object.keys(jogos).forEach(nome => {
            const valores = atualizarValores(jogos[nome]);
            resposta += formatarEstatistica(nome, valores);
        });
        return resposta + "Observação: As porcentagens podem conter alguma divergência...";
    }

    const jogoData = jogos[jogo];
    if (!jogoData) return `❌ Jogo "${jogo}" não encontrado.`;

    const valores = atualizarValores(jogoData);
    return header + formatarEstatistica(jogo, valores) + "Observação: As porcentagens podem conter alguma divergência...";
}


// --- 3. FLUXO DE EXECUÇÃO (Inicialização e Teste) ---

/**
 * Inicializa ou carrega os arquivos de dados (relacionamentos e aki).
 */
function inicializarDados() {
    // Inicialização de relacionamentos.json
    if (!fs.existsSync(CASAMENTO_JSON_PATH)) {
        fs.writeFileSync(CASAMENTO_JSON_PATH, JSON.stringify({ casamentos: [], namoros: [] }, null, 2));
    } else {
        try {
            const data = JSON.parse(fs.readFileSync(CASAMENTO_JSON_PATH, 'utf-8'));
            // Garante que as chaves existam
            if (!data.casamentos || !data.namoros) {
                fs.writeFileSync(CASAMENTO_JSON_PATH, JSON.stringify({ casamentos: [], namoros: [] }, null, 2));
            }
        } catch (error) {
            console.error(`Erro ao ler ou parsear ${CASAMENTO_JSON_PATH}:`, error.message);
        }
    }

    // Leitura final de relacionamentos (após garantir a estrutura)
    try {
        const relacionamentos = JSON.parse(fs.readFileSync(CASAMENTO_JSON_PATH, 'utf-8'));
        console.log("Relacionamentos carregados com sucesso.");
    } catch (e) {
        console.error("Não foi possível carregar os relacionamentos finais.");
    }


    // Inicialização de aki.json
    let akiData = {};
    if (fs.existsSync(AKI_JSON_PATH)) {
        try {
            akiData = JSON.parse(fs.readFileSync(AKI_JSON_PATH, 'utf-8'));
            console.log("aki.json carregado com sucesso.");
        } catch (error) {
            console.error(`Erro ao ler ou parsear ${AKI_JSON_PATH}:`, error.message);
        }
    } else {
        console.log("aki.json não encontrado. Criando estrutura vazia se necessário.");
        // Aqui você pode adicionar lógica para criar o arquivo se ele não existir
    }
    return { relacionamentos, akiData };
}


// --- EXEMPLO DE USO (Simulação de como o código funcionaria) ---
